"""Expose the package version in source checkouts and installed distributions."""

__all__ = ["__version__"]

try:
    from ._version import version as __version__
except ImportError:
    # ``_version.py`` is generated by setuptools-scm during a package build.
    # Keep direct source checkouts usable before that build step has run.
    __version__ = "0.0.1"
